## API exports for siblings B and C

From `src/renderer/store/edges.ts`:
```ts
export type EdgeSide = "top" | "right" | "bottom" | "left";
export type EdgeEnd = "none" | "arrow";
export interface Edge {
  id: string;
  fromNode: string;
  toNode: string;
  fromSide?: EdgeSide;
  toSide?: EdgeSide;
  fromEnd?: EdgeEnd;   // default "none"
  toEnd?: EdgeEnd;     // default "arrow"
  color?: Color;
  label?: string;
}
export interface EdgesState {
  edges: Edge[];
  addEdge(e: Edge): void;
  updateEdge(id: string, patch: Partial<Edge>): void;
  deleteEdge(id: string): void;
  deleteEdgesForNode(nodeId: string): Edge[];
}
export const useEdges: UseBoundStore<StoreApi<EdgesState>>;
export function makeEdgeId(): string;
export function deleteNodeAndEdges(nodeId: string): { removedEdges: Edge[] };
```

From `src/renderer/canvas/edges/geometry.ts`:
```ts
export const EDGE_ARROW_SIZE = 12;
export const EDGE_CONTROL_OFFSET_MIN = 40;
export const EDGE_CONTROL_OFFSET_MAX = 200;
export type EdgeSide = "top" | "right" | "bottom" | "left";
export interface Point { x: number; y: number; }
export interface Rect { x: number; y: number; width: number; height: number; }
export function anchorPosition(node: Rect, side: EdgeSide): Point;
export function defaultSidesFor(fromNode: Rect, toNode: Rect): { fromSide: EdgeSide; toSide: EdgeSide };
export function bezierControlPoints(from: Point, to: Point, fromSide: EdgeSide, toSide: EdgeSide): { c1: Point; c2: Point };
export function arrowHeadPoints(tip: Point, fromControl: Point, size: number): [Point, Point, Point];
```

